// Demo: Signature Markov-Chain Page Prefetch — Markov next-page prediction over 1 transitions
var pages=['home','search','product','cart','checkout'];var trans={};
for(var i=0;i<1;i++){var a=pages[(i*7+1)%5],b=pages[(i*13+1)%5];(trans[a]=trans[a]||{})[b]=((trans[a]||{})[b]||0)+1;}
var cur='product';var best=null,bn=-1;Object.keys(trans[cur]||{}).forEach(function(k){if(trans[cur][k]>bn){bn=trans[cur][k];best=k;}});
console.log('technique: Signature Markov-Chain Page Prefetch');console.log('current page: '+cur);
console.log('predicted next: '+best+' ('+bn+' observed transitions)');console.log('action: prefetch '+best+' during idle time');

// Demo: Signature Scroll-Velocity Prefetch — scroll-velocity lookahead
var positions=[];for(var i=0;i<10;i++){positions.push(i*i*2+(i*2%7));}
var v=positions[positions.length-1]-positions[positions.length-2];
var lookahead=Math.min(20,Math.max(0,Math.round(v/50)));
console.log('technique: Signature Scroll-Velocity Prefetch');console.log('scroll velocity: '+v+' px/frame');
console.log('prefetch '+lookahead+' items ahead of the viewport');

// Demo: Signature DNS Pre-Resolve Hints — bandwidth budget guard
function budget(bytesPerSec){var cap=bytesPerSec*0.2;return cap;}
var bw=28*1000;var cap=budget(bw);var items=[];var used=0;
for(var i=0;i<16;i++){var sz=20000+((i*31+3)%80000);if(used+sz<=cap){items.push(sz);used+=sz;}}
console.log('technique: Signature DNS Pre-Resolve Hints');console.log('bandwidth: '+(bw/1000)+' KB/s, prefetch cap: '+(cap/1000).toFixed(0)+' KB');
console.log('prefetched '+items.length+' items ('+(used/1000).toFixed(0)+' KB) without starving foreground traffic');

